import { useCallback, useEffect, useRef, useState } from 'react';
import {
  Box,
  Typography,
  Stack,
  CircularProgress,
  Chip,
} from '@mui/material';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import ErrorOutlineIcon from '@mui/icons-material/ErrorOutlineOutlined';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { toast } from 'react-hot-toast';
import GlowButton from '../components/ui/GlowButton';
import {
  useSignup,
  completionKey,
} from '../context/SignupContext';
import { verifyPayment } from '../../../utils/stripeApi';
import { registerUser } from '../../../utils/userApi';
import { APP_STORE_URL } from '../constants/plans';
import { BRAND, TOKENS } from '../theme';

const cardSx = {
  width: '100%',
  maxWidth: 460,
  mx: 'auto',
  p: { xs: 3, sm: 4.5 },
  borderRadius: '20px',
  border: `1px solid ${TOKENS.card.border}`,
  bgcolor: TOKENS.card.bgcolor,
  backdropFilter: 'blur(24px)',
  boxShadow: TOKENS.card.shadow,
};

const formatDate = (unixSeconds) => {
  if (!unixSeconds) return null;
  try {
    return new Date(unixSeconds * 1000).toLocaleDateString(undefined, {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  } catch {
    return null;
  }
};

const StoreBadge = ({ href, src, alt }) => (
  <Box
    component="a"
    href={href}
    target="_blank"
    rel="noopener noreferrer"
    sx={{
      display: 'inline-flex',
      bgcolor: '#000',
      borderRadius: '8px',
      border: '1px solid rgba(255,255,255,0.35)',
      transition: 'transform 0.2s ease',
      '&:hover': { transform: 'translateY(-2px)' },
    }}
  >
    <Box component="img" src={src} alt={alt} sx={{ height: 44, width: 'auto' }} />
  </Box>
);

const PaymentSuccessPage = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { selectedPlan, signupData, clearSignupData, clearSelectedPlan, getPlanLabel, setSubscription } = useSignup();

  const [status, setStatus] = useState('processing');
  const [phase, setPhase] = useState('verifying');
  const [payment, setPayment] = useState(null);
  const [errorMessage, setErrorMessage] = useState('');
  const [errorAction, setErrorAction] = useState('plans');

  const hasRun = useRef(false);
  const verifiedRef = useRef(null);

  const runRegistration = useCallback(async () => {
    if (!signupData?.email || !signupData?.password) {
      setStatus('error');
      setErrorAction('plans');
      setErrorMessage('Your signup details were not found. Please start again from signup.');
      return;
    }

    setStatus('processing');
    setPhase('registering');

    try {
      await registerUser({
        name: signupData.fullName,
        email: signupData.email,
        password: signupData.password,
        confirmPassword: signupData.password,
      });

      const sessionId = searchParams.get('session_id');
      if (sessionId && verifiedRef.current) {
        try {
          sessionStorage.setItem(
            completionKey(sessionId),
            JSON.stringify(verifiedRef.current),
          );
        } catch {
          // non-fatal
        }
      }

      clearSignupData();
      clearSelectedPlan();
      setStatus('success');
    } catch (error) {
      setStatus('error');
      setErrorAction('retry-register');
      setErrorMessage(error.message || 'We could not create your account.');
    }
  }, [signupData, searchParams, clearSignupData, clearSelectedPlan]);

  useEffect(() => {
    if (hasRun.current) return;
    hasRun.current = true;

    const sessionId = searchParams.get('session_id');
    if (!sessionId) {
      setStatus('error');
      setErrorAction('plans');
      setErrorMessage('Missing session information. Please try again.');
      return;
    }

    try {
      const cached = sessionStorage.getItem(completionKey(sessionId));
      if (cached) {
        const data = JSON.parse(cached);
        setPayment(data);
        setSubscription(data);
        setStatus('success');
        return;
      }
    } catch {
      // continue
    }

    const run = async () => {
      try {
        const data = await verifyPayment({
          sessionId,
          planId: selectedPlan?.planId,
        });

        if (!data?.verified) throw new Error('Payment could not be verified.');

        verifiedRef.current = data;
        setPayment(data);
        setSubscription(data);
      } catch (error) {
        setStatus('error');
        setErrorAction('plans');
        setErrorMessage(error.message || 'We could not verify your payment.');
        return;
      }

      await runRegistration();
    };

    run();
  }, [searchParams, selectedPlan, setSubscription, runRegistration]);

  if (status === 'processing') {
    return (
      <Box sx={cardSx}>
        <Stack spacing={3} alignItems="center" sx={{ py: 3 }}>
          <CircularProgress size={52} sx={{ color: BRAND.green }} />
          <Box sx={{ textAlign: 'center' }}>
            <Typography variant="h5" sx={{ fontWeight: 700, mb: 0.5 }}>
              {phase === 'registering' ? 'Setting up your account' : 'Verifying your payment'}
            </Typography>
            <Typography variant="body2" sx={{ color: 'text.secondary' }}>
              Please wait a moment, this won't take long.
            </Typography>
          </Box>
        </Stack>
      </Box>
    );
  }

  if (status === 'error') {
    return (
      <Box sx={cardSx}>
        <Stack spacing={3} alignItems="center">
          <ErrorOutlineIcon sx={{ fontSize: 56, color: 'error.main' }} />
          <Box sx={{ textAlign: 'center' }}>
            <Typography variant="h5" sx={{ fontWeight: 800, mb: 1 }}>
              {errorAction === 'retry-register' ? 'Account Setup Failed' : 'Verification Failed'}
            </Typography>
            <Typography variant="body2" sx={{ color: 'text.secondary' }}>
              {errorMessage}
            </Typography>
            {errorAction === 'retry-register' && (
              <Typography variant="body2" sx={{ color: 'text.secondary', mt: 1 }}>
                Your payment was successful - you can safely retry creating your account.
              </Typography>
            )}
          </Box>
          {errorAction === 'retry-register' ? (
            <GlowButton fullWidth onClick={() => { toast.dismiss(); runRegistration(); }}>
              Retry
            </GlowButton>
          ) : (
            <GlowButton fullWidth variant="outlined" onClick={() => navigate('/plans')}>
              Back to Plans
            </GlowButton>
          )}
        </Stack>
      </Box>
    );
  }

  const renewal = formatDate(payment?.current_period_end);
  const planLabel = getPlanLabel() || selectedPlan?.name || '-';
  const statusLabel = payment?.status || 'active';

  return (
    <Box sx={{ width: '100%', px: { xs: 1, sm: 0 } }}>
      <Box sx={cardSx}>
      <Stack spacing={3} alignItems="center">
        <CheckCircleIcon sx={{ fontSize: 56, color: BRAND.green }} />
        <Box sx={{ textAlign: 'center' }}>
          <Typography variant="h4" sx={{ fontWeight: 800, letterSpacing: '-0.03em', mb: 1 }}>
            Your account is ready!
          </Typography>
          <Typography variant="body2" sx={{ color: 'text.secondary', lineHeight: 1.7 }}>
            Your payment is confirmed and your account has been created. Download the app and log in with the{' '}
            <Box component="span" sx={{ color: TOKENS.colors.textPrimary, fontWeight: 600 }}>
              same email and password
            </Box>{' '}
            you entered at signup.
          </Typography>
        </Box>

        {payment && (
          <Box
            sx={{
              width: '100%',
              p: 2,
              borderRadius: '14px',
              border: `1px solid ${TOKENS.colors.border}`,
              bgcolor: TOKENS.colors.surface,
            }}
          >
            <Stack spacing={1.25}>
              <Stack direction="row" justifyContent="space-between">
                <Typography variant="body2" sx={{ color: 'text.secondary' }}>Plan</Typography>
                <Typography variant="body2" sx={{ fontWeight: 600 }}>{planLabel}</Typography>
              </Stack>
              <Stack direction="row" justifyContent="space-between" alignItems="center">
                <Typography variant="body2" sx={{ color: 'text.secondary' }}>Status</Typography>
                <Chip
                  label={statusLabel.toUpperCase()}
                  size="small"
                  sx={{ bgcolor: 'rgba(76,198,110,0.15)', color: BRAND.green, fontWeight: 700, fontSize: '0.65rem' }}
                />
              </Stack>
              {renewal && (
                <Stack direction="row" justifyContent="space-between">
                  <Typography variant="body2" sx={{ color: 'text.secondary' }}>
                    {statusLabel === 'trialing' ? 'Trial ends' : 'Renews on'}
                  </Typography>
                  <Typography variant="body2" sx={{ fontWeight: 600 }}>{renewal}</Typography>
                </Stack>
              )}
            </Stack>
          </Box>
        )}

        <Box sx={{ width: '100%', textAlign: 'center' }}>
          <Typography variant="caption" sx={{ color: 'text.secondary', letterSpacing: '0.1em', mb: 1.5, display: 'block' }}>
            GET THE APP
          </Typography>
          <StoreBadge href={APP_STORE_URL} src="/badges/app-store.svg" alt="Download on the App Store" />
          <Stack direction="row" spacing={0.75} justifyContent="center" alignItems="center" sx={{ mt: 2 }}>
            <Box component="img" src="/badges/google-play-icon.svg" alt="" sx={{ height: 14, opacity: 0.5 }} />
            <Typography variant="caption" sx={{ color: 'text.secondary' }}>
              Android app coming soon on Google Play
            </Typography>
          </Stack>
        </Box>
      </Stack>
      </Box>
    </Box>
  );
};

export default PaymentSuccessPage;
