import { apiFetch } from './apiClient';

const parseJson = async (response) => {
  const json = await response.json().catch(() => ({}));
  if (!response.ok || json?.error) {
    const error = new Error(
      json?.message || json?.message_en || `Request failed: ${response.status}`,
    );
    error.status = response.status;
    error.data = json;
    throw error;
  }
  return json;
};

// Checks whether an email is already registered (public, no auth).
export const checkEmail = async (email) => {
  const response = await apiFetch('/users/check-email', null, {
    method: 'POST',
    body: { email },
  });
  const json = await parseJson(response);
  return json.data ?? json;
};

// Registers a user via the public "add user" endpoint (POST /users).
// For the pay-first web flow, is_lifetime_free stays true. No JWT required.
export const registerUser = async (payload) => {
  const response = await apiFetch('/users', null, {
    method: 'POST',
    body: {
      name: payload.name,
      email: payload.email,
      password: payload.password,
      confirm_password: payload.confirmPassword ?? payload.password,
      is_lifetime_free: true,
    },
  });
  const json = await parseJson(response);
  return json.data ?? json;
};

// Admin-only: reset a user's password without old password or OTP.
export const resetUserPassword = async (userId, newPassword, token) => {
  const response = await apiFetch(`/users/${userId}/password`, token, {
    method: 'PATCH',
    body: { newPassword },
  });
  const json = await parseJson(response);
  return json.data ?? json;
};
